import{_ as t,o as a,c as o,au as d}from"./chunks/framework.BTTEhLNX.js";const b=JSON.parse(`{"title":"krawler-hubeau","description":"A Krawler based job to download data from the Hub'Eau API.","frontmatter":{"title":"krawler-hubeau","description":"A Krawler based job to download data from the Hub'Eau API."},"headers":[],"relativePath":"packages/krawler-hubeau/index.md","filePath":"packages/krawler-hubeau/index.md"}`),r={name:"packages/krawler-hubeau/index.md"};function i(l,e,s,n,u,c){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="krawler-hubeau" tabindex="-1">krawler-hubeau <a class="header-anchor" href="#krawler-hubeau" aria-label="Permalink to &quot;krawler-hubeau&quot;">​</a></h1><p><em>A Krawler based job to download data from French open portal <a href="https://hubeau.eaufrance.fr/" target="_blank" rel="noreferrer">Hub&#39;Eau</a>.</em></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>A <a href="https://kalisio.github.io/krawler/" target="_blank" rel="noreferrer">Krawler</a> based service to download data from French open portal <a href="https://hubeau.eaufrance.fr/" target="_blank" rel="noreferrer">Hub&#39;Eau</a>.</p><h2 id="k-hubeau-hydro" tabindex="-1">K-hubeau-hydro <a class="header-anchor" href="#k-hubeau-hydro" aria-label="Permalink to &quot;K-hubeau-hydro&quot;">​</a></h2><p>The <strong>krawler-hubeau-hydro</strong> jobs allow to scrape hydrometric data from the following api: <a href="http://hubeau.eaufrance.fr/page/api-hydrometrie" target="_blank" rel="noreferrer">http://hubeau.eaufrance.fr/page/api-hydrometrie</a>. The downloaded data are stored in a <a href="https://www.mongodb.com/" target="_blank" rel="noreferrer">MongoDB</a> database and more precisely in 2 collections:</p><ul><li>the <code>observations</code> collection stores the observed data: <ul><li>the water level <code>H</code> in meter (m)</li><li>the water flow <code>Q</code> in cubic meter per second (m3/s)</li></ul></li><li>the <code>stations</code> collection stores the data of the stations</li></ul><p>The project consists in 3 jobs:</p><ul><li>the <code>stations</code> job scrapes the stations data according a specific cron expression. By default, every day at midnight.</li><li>the <code>observations</code> job scrapes the observations according a specific cron expression. By default every 15 minutes.</li><li>the <code>prediction</code> job generates the predictions about future water levels.</li></ul><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><h4 id="stations" tabindex="-1">Stations <a class="header-anchor" href="#stations" aria-label="Permalink to &quot;Stations&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>DB_URL</code></td><td>The database URL. The default value is <code>mongodb://127.0.0.1:27017/hubeau</code></td></tr><tr><td><code>DEBUG</code></td><td>Enables debug output. Set it to <code>krawler*</code> to enable full output. By default it is undefined.</td></tr></tbody></table><h4 id="observations" tabindex="-1">Observations <a class="header-anchor" href="#observations" aria-label="Permalink to &quot;Observations&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>DB_URL</code></td><td>The database URL. The default value is <code>mongodb://127.0.0.1:27017/hubeau</code></td></tr><tr><td><code>TTL</code></td><td>The observations data time to live. It must be expressed in seconds and the default value is <code>604 800</code> (7 days)</td></tr><tr><td><code>HISTORY</code></td><td>The duration of the observations data history the job has to download. It must be expressed in milliseconds and the default value is <code>86 400 000</code> (1 day)</td></tr><tr><td><code>TIMEOUT</code></td><td>The maximum duration of the job. It must be in milliseconds and the default value is <code>1 800 000</code> (30 minutes).</td></tr><tr><td><code>DEBUG</code></td><td>Enables debug output. Set it to <code>krawler*</code> to enable full output. By default it is undefined.</td></tr></tbody></table><h2 id="k-hubeau-piezo" tabindex="-1">K-hubeau-piezo <a class="header-anchor" href="#k-hubeau-piezo" aria-label="Permalink to &quot;K-hubeau-piezo&quot;">​</a></h2><p>The <strong>krawler-hubeau-piezo</strong> jobs allow to scrape piezometric data from the following api: <a href="http://hubeau.eaufrance.fr/page/api-piezometrie" target="_blank" rel="noreferrer">http://hubeau.eaufrance.fr/page/api-piezometrie</a>. The downloaded data are stored in a <a href="https://www.mongodb.com/" target="_blank" rel="noreferrer">MongoDB</a> database and more precisely in 2 collections:</p><ul><li><p>the <code>observations</code> collection stores the observed data:</p><ul><li>the water table level <code>profondeur_nappe</code> in meter (m)</li><li>the water table level in ngf format <code>niveau_eau_ngf</code> in meter (m)</li></ul></li><li><p>the <code>stations</code> collection stores the data of the stations</p><ul><li>the field <code>DATE_FIN_MESURE</code> is used to define older stations as inactive (<code>is_active: false</code>) and should not be requested by the observations job.</li></ul></li></ul><p>The project consists in 2 jobs:</p><ul><li>the <code>stations</code> job scrapes the stations data according a specific cron expression. By default, every day at midnight.</li><li>the <code>observations</code> job scrapes the observations according a specific cron expression. By default every hour at 15 minutes.</li></ul><h3 id="configuration-1" tabindex="-1">Configuration <a class="header-anchor" href="#configuration-1" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><h4 id="stations-1" tabindex="-1">Stations <a class="header-anchor" href="#stations-1" aria-label="Permalink to &quot;Stations&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>DB_URL</code></td><td>The database URL. The default value is <code>mongodb://127.0.0.1:27017/hubeau</code></td></tr><tr><td><code>CODE_DEP</code></td><td>list of department codes to filter the stations. (ie: <code>&quot;75&quot;, &quot;92&quot;</code>), default is all 101 french departments</td></tr><tr><td><code>DATE_FIN_MESURE</code></td><td>Deadline defining all older stations as inactive, default is <code>2022-01-01</code></td></tr><tr><td><code>DEBUG</code></td><td>Enables debug output. Set it to <code>krawler*</code> to enable full output. By default it is undefined.</td></tr></tbody></table><h4 id="observations-1" tabindex="-1">Observations <a class="header-anchor" href="#observations-1" aria-label="Permalink to &quot;Observations&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>DB_URL</code></td><td>The database URL. The default value is <code>mongodb://127.0.0.1:27017/hubeau</code></td></tr><tr><td><code>TTL</code></td><td>The observations data time to live. It must be expressed in seconds and the default value is <code>604 800</code> (7 days)</td></tr><tr><td><code>HISTORY</code></td><td>The duration of the observations data history the job has to download. It must be expressed in milliseconds (should be full days) and the default value is <code>86 400 000</code> (1 day)</td></tr><tr><td><code>TIMEOUT</code></td><td>The maximum duration of the job. It must be in milliseconds and the default value is <code>1 800 000</code> (30 minutes).</td></tr><tr><td><code>DEBUG</code></td><td>Enables debug output. Set it to <code>krawler*</code> to enable full output. By default it is undefined.</td></tr></tbody></table><h2 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h2><p>We personally use <a href="https://kalisio.github.io/kargo/" target="_blank" rel="noreferrer">Kargo</a> to deploy the service.</p>',26)])])}const f=t(r,[["render",i]]);export{b as __pageData,f as default};
